// src/services/core/errorHandler.ts
function handleServiceError(error, defaultCode = "UNKNOWN_ERROR") {
  if (error instanceof AppError) {
    return error;
  }
  console.error("[Service Error]", error);
  if (error?.code === "PGRST301") {
    return new AppError("AUTHENTICATION_REQUIRED", "Please sign in to continue.");
  }
  if (error?.code && error.code.startsWith("23")) {
    return new AppError("CONFLICT", "A data conflict occurred.", error);
  }
  return new AppError(
    defaultCode,
    error?.message || "An unexpected error occurred.",
    error
  );
}

